#!/usr/bin/env python3
"""Instala o código completo Nuvem TV no repositório atual, sem baixar fontes."""
import argparse,base64,hashlib,io,zipfile
from pathlib import Path
p=argparse.ArgumentParser(description=__doc__)
p.add_argument('--sem-workflow',action='store_true',help='criar o workflow depois pelo editor do GitHub')
p.add_argument('--substituir',action='store_true',help='substituir arquivos existentes; use somente em seu projeto novo')
a=p.parse_args()
DATA=""""""
data=base64.b64decode(DATA)
assert hashlib.sha256(data).hexdigest()=="a01c0745d6b3a608a4a9aa2835ce23488cef616f7a402b4fc0506260575ef878", "Arquivo do instalador foi alterado"
root=Path.cwd().resolve()
with zipfile.ZipFile(io.BytesIO(data)) as z:
    items=[]
    for info in z.infolist():
        path=Path(info.filename)
        if a.sem_workflow and path.parts[0]=='.github': continue
        target=(root/path).resolve()
        if path.is_absolute() or root not in target.parents: raise SystemExit('Caminho inválido no pacote')
        body=z.read(info)
        if target.exists() and target.read_bytes()!=body and not a.substituir: raise SystemExit(f'{path} já existe. Use --substituir somente no repositório novo.')
        items.append((target,body))
    for target,body in items:
        target.parent.mkdir(parents=True,exist_ok=True)
        target.write_bytes(body)
(root/'gradlew').chmod(0o755)
print(f'Pronto: {len(items)} arquivos criados na raiz do seu repositório.')
print('Agora execute git add ., git commit e git push, conforme o guia.')
